import thaumcraft.devices.AuraDeviceEntity;
public final class SealEntity extends AuraDeviceEntity implements MenuProvider {
    private static final Map<ServerLevel,Map<BlockPos,SealEntity>> INDEX=new WeakHashMap<>();
    private UUID owner,worker;private long lease;public int channel,priority,radius=3;public boolean redstone=true,blacklist;public ItemStack filter=ItemStack.EMPTY;
    public final net.minecraft.core.NonNullList<ItemStack> extraFilters=net.minecraft.core.NonNullList.withSize(8,ItemStack.EMPTY);public final int[] amounts={64,64,64,64,64,64,64,64,64};public boolean exact=true,silk;public int guardMode;public int guardMask=-1;public boolean shared;public boolean useLeft,useAir,useEmpty,useSneak,useProvision;private int revision;
    public boolean matchDamage=true,matchTags,matchMod,leaveOne,single,cycle,existingOnly;public boolean replant=true,harvestProvision;private int filterCursor;public final Map<BlockPos,BlockState> replants=new LinkedHashMap<>();
    private SealArea configuredArea;private boolean oriented;
    public SealArea areaConfig(){return configuredArea==null?SealArea.initial(getBlockState().getValue(SealBlock.FACING)):configuredArea;}
    public boolean oriented(){return oriented&&kind().hasArea();}
    public net.minecraft.world.phys.AABB area(){return oriented()?areaConfig().bounds(support(),getBlockState().getValue(SealBlock.FACING)):new net.minecraft.world.phys.AABB(worldPosition).inflate(radius);}
    public int revision(){return revision;}
    public ItemStack sample(int i){return i==0?filter:i>0&&i<kind().filterSlots()?extraFilters.get(i-1):ItemStack.EMPTY;}
    public static boolean same(ItemStack a,ItemStack b,boolean exact){return !a.isEmpty()&&!b.isEmpty()&&(exact?ItemStack.isSameItemSameComponents(a.copyWithCount(1),b.copyWithCount(1)):a.is(b.getItem()));}
    public boolean matchesSample(ItemStack a,ItemStack b){return SealMatching.matches(a,b,exact,matchDamage,matchTags,matchMod);}
    public int extractionLimit(ItemStack stack,int desired){return Math.max(0,Math.min(single&&kind()==SealKind.PROVIDER?1:desired,leaveOne?count(stack)-1:Integer.MAX_VALUE));}
    public boolean acceptsExtraction(ItemStack stack){if(!matches(stack))return false;if(!cycle||kind()!=SealKind.EMPTY_ADVANCED||blacklist)return true;for(int n=0;n<kind().filterSlots();n++){int i=(filterCursor+n)%kind().filterSlots();if(!sample(i).isEmpty()&&count(sample(i))>(leaveOne?1:0))return matchesSample(stack,sample(i));}return false;}
    public void extracted(ItemStack stack){if(cycle)for(int n=0;n<kind().filterSlots();n++){int i=(filterCursor+n)%kind().filterSlots();if(matchesSample(stack,sample(i))){filterCursor=(i+1)%kind().filterSlots();setChanged();break;}}}
    public int fillLimit(ItemStack stack){if(!matches(stack)||existingOnly&&count(stack)==0)return 0;if(kind()!=SealKind.FILL_ADVANCED||blacklist)return stack.getCount();int limit=0;boolean any=false;for(int n=0;n<kind().filterSlots();n++)if(!sample(n).isEmpty()){any=true;if(matchesSample(stack,sample(n)))limit=Math.max(limit,amounts[n]-count(sample(n)));}return any?Math.max(0,Math.min(stack.getCount(),limit)):stack.getCount();}
    public void sample(int i,ItemStack s){if(i<0||i>=kind().filterSlots())return;if(i==0)filter=s.copyWithCount(1);else extraFilters.set(i-1,s.copyWithCount(1));revision++;worker=null;sync();}
    public int count(ItemStack sample){var h=handler();int count=0;if(h!=null)for(int i=0;i<Math.min(256,h.getSlots());i++)if(matchesSample(h.getStackInSlot(i),sample))count=(int)Math.min(Integer.MAX_VALUE,(long)count+h.getStackInSlot(i).getCount());if(h==null&&kind().base()==SealKind.FILL&&level instanceof ServerLevel server)for(var item:server.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(worldPosition).inflate(1.5)))if(matchesSample(item.getItem(),sample))count=(int)Math.min(Integer.MAX_VALUE,(long)count+item.getItem().getCount());return count;}
    public int wanted(ItemStack stack){if(kind()==SealKind.HARVEST)return harvestProvision&&replant&&GolemCrops.pending(this,stack)!=null?1:0;if(kind()==SealKind.USE)return useProvision&&!useEmpty&&!blacklist&&!filter.isEmpty()&&matches(stack)?1:0;if(kind()!=SealKind.STOCK)return 0;int target=0;for(int i=0;i<kind().filterSlots();i++)if(matchesSample(stack,sample(i)))target=Math.max(target,amounts[i]);return Math.max(0,target-count(stack));}
    public SealEntity(BlockPos p,BlockState s){super(GolemContent.SEAL_TYPE.get(),p,s);}
    public SealKind kind(){return ((SealBlock)getBlockState().getBlock()).kind;}public UUID owner(){return owner;}public void claimOwner(Player p){if(owner==null){owner=p.getUUID();sync();}}
    public int targets(){return guardMask<0?1<<guardMode:guardMask;}
    public boolean allows(WorkerGolem g){return owner!=null&&(shared||owner.equals(g.ownerId()));}
    public boolean owned(Player p){return owner!=null&&owner.equals(p.getUUID());}public boolean valid(Player p){return owned(p)&&level==p.level()&&level.getBlockEntity(worldPosition)==this&&p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(worldPosition))<=64;}
    public boolean active(){return level!=null&&!isRemoved()&&level.hasChunkAt(worldPosition)&&level.getBlockEntity(worldPosition)==this&&(!redstone||!level.hasNeighborSignal(worldPosition))&&getBlockState().canSurvive(level,worldPosition);}
    public boolean matches(ItemStack s){if(s.isEmpty())return false;boolean any=false,match=false;for(int i=0;i<kind().filterSlots();i++){var f=sample(i);if(!f.isEmpty()){any=true;if(matchesSample(s,f))match=true;}}if(kind()==SealKind.STOCK)return match;return blacklist?any&&!match:!any||match;}
    public boolean claim(WorkerGolem g){long now=level.getGameTime();if(!active()||!g.withinWorkArea(worldPosition)||!allows(g)||g.channel()!=channel||!kind().accepts(g.design())||worker!=null&&!worker.equals(g.getUUID())&&lease>now)return false;worker=g.getUUID();lease=now+100;return true;}
    public void release(WorkerGolem g){if(g.getUUID().equals(worker)){worker=null;lease=0;}}
    public BlockPos support(){return worldPosition.relative(getBlockState().getValue(SealBlock.FACING).getOpposite());}
    public BlockPos useTarget(){return useAir?getBlockPos().relative(getBlockState().getValue(SealBlock.FACING)):support();}
    public boolean useReady(){return level!=null&&level.hasChunkAt(useTarget())&&level.isEmptyBlock(useTarget())==useAir;}
    public IItemHandler handler(){var p=support();if(level==null||!level.hasChunkAt(p))return null;var be=level.getBlockEntity(p);return be==null?null:be.getCapability(ForgeCapabilities.ITEM_HANDLER,getBlockState().getValue(SealBlock.FACING)).orElse(null);}
    public static List<SealEntity> nearby(ServerLevel l,WorkerGolem g){var map=INDEX.get(l);if(map==null)return List.of();return map.values().stream().filter(s->s.active()&&s.allows(g)&&s.channel==g.channel()&&g.withinWorkArea(s.worldPosition)&&s.kind().accepts(g.design())).sorted(Comparator.<SealEntity>comparingInt(s->-s.priority).thenComparingDouble(s->s.worldPosition.distSqr(g.blockPosition()))).toList();}
    public void serverTick(){if(level instanceof ServerLevel l){INDEX.computeIfAbsent(l,k->new HashMap<>()).put(worldPosition,this);if(!getBlockState().canSurvive(l,worldPosition))l.destroyBlock(worldPosition,true);}}
    public static void unload(net.minecraft.world.level.Level l){if(l instanceof ServerLevel s)INDEX.remove(s);}
    public void setRemoved(){if(level instanceof ServerLevel l){var map=INDEX.get(l);if(map!=null)map.remove(worldPosition,this);}super.setRemoved();}
    public boolean edit(Player p,int button){return edit(p,button,0);}
    public boolean edit(Player p,int button,int selected){if(!valid(p)||selected<0||selected>=kind().filterSlots()||!kind().hasFilters()&&(button==4||button==5||button==6))return false;switch(button){case 0->channel=(channel+1)%16;case 1->priority=priority==5?-5:priority+1;case 2->{if(oriented())return false;radius=radius==8?1:radius+1;}case 3->redstone=!redstone;case 4->{var held=p.getMainHandItem();if(held.getItem() instanceof GolemBell)held=p.getOffhandItem();sample(selected,held);if((kind()==SealKind.STOCK||kind()==SealKind.FILL_ADVANCED)&&!held.isEmpty())amounts[selected]=Math.clamp(held.getCount(),1,4096);}case 5->sample(selected,ItemStack.EMPTY);case 6->{if(kind()==SealKind.STOCK)return false;blacklist=!blacklist;}case 7->{if(!kind().advanced()&&kind()!=SealKind.PROVIDER&&kind()!=SealKind.STOCK&&kind()!=SealKind.USE)return false;exact=!exact;matchDamage=exact;}case 8->{if(kind()!=SealKind.STOCK&&kind()!=SealKind.FILL_ADVANCED)return false;amounts[selected]=Math.min(4096,amounts[selected]+1);}case 9->{if(kind()!=SealKind.STOCK&&kind()!=SealKind.FILL_ADVANCED)return false;amounts[selected]=Math.max(1,amounts[selected]-1);}case 10->{if(kind()!=SealKind.GUARD_ADVANCED)return false;guardMode=(guardMode+1)%3;guardMask=-1;}case 11->{if(kind()!=SealKind.BREAKER_ADVANCED)return false;silk=!silk;}case 12,13,14,15,16->{if(kind()!=SealKind.USE)return false;switch(button){case 12->useLeft=!useLeft;case 13->useAir=!useAir;case 14->useEmpty=!useEmpty;case 15->useSneak=!useSneak;case 16->useProvision=!useProvision;}}case 17->{if(!kind().hasArea())return false;oriented=!oriented;}case 18,19,20,21,22,23->{if(!kind().hasArea()||!oriented())return false;var next=areaConfig().change((button-18)/2,button%2==0?-1:1);if(next.equals(areaConfig()))return false;configuredArea=next;}case 24,25,26->{if(!kind().hasFilters()||!kind().advanced()&&kind()!=SealKind.PROVIDER&&kind()!=SealKind.STOCK&&kind()!=SealKind.USE)return false;switch(button){case 24->matchDamage=!matchDamage;case 25->matchTags=!matchTags;case 26->matchMod=!matchMod;}}case 27,28,29,30,31,32->{switch(button){case 27->{if(kind()!=SealKind.EMPTY_ADVANCED&&kind()!=SealKind.PROVIDER)return false;leaveOne=!leaveOne;}case 28->{if(kind()!=SealKind.PROVIDER)return false;single=!single;}case 29->{if(kind()!=SealKind.EMPTY_ADVANCED)return false;cycle=!cycle;}case 30->{if(kind()!=SealKind.FILL_ADVANCED)return false;existingOnly=!existingOnly;}case 31->{if(kind()!=SealKind.HARVEST)return false;replant=!replant;}case 32->{if(kind()!=SealKind.HARVEST)return false;harvestProvision=!harvestProvision;}}}case 33,34,35->{if(kind()!=SealKind.GUARD_ADVANCED)return false;guardMask=targets()^(1<<(button-33));}case 36->shared=!shared;default->{return false;}}revision++;worker=null;sync();return true;}
    public Component getDisplayName(){return Component.translatable("item.thaumcraft.seal_"+kind().id());}public AbstractContainerMenu createMenu(int id,Inventory inv,Player p){return new SealMenu(id,inv,this);}
    protected void saveAdditional(ValueOutput o){super.saveAdditional(o);if(owner!=null)o.putString("owner",owner.toString());o.putInt("channel",channel);o.putInt("priority",priority);o.putInt("radius",radius);o.putBoolean("oriented_area",oriented());o.store("seal_area",SealArea.CODEC,areaConfig());o.putBoolean("redstone",redstone);o.putBoolean("blacklist",blacklist);o.store("filter",ItemStack.OPTIONAL_CODEC,filter);o.store("filters",net.minecraft.world.item.component.ItemContainerContents.CODEC,net.minecraft.world.item.component.ItemContainerContents.fromItems(extraFilters));var plantData=new LinkedHashMap<String,BlockState>();replants.forEach((p,s)->plantData.put(Long.toString(p.asLong()),s));o.store("replants",com.mojang.serialization.Codec.unboundedMap(com.mojang.serialization.Codec.STRING,BlockState.CODEC),plantData);o.putBoolean("leave_one",leaveOne);o.putBoolean("single",single);o.putBoolean("cycle",cycle);o.putBoolean("existing_only",existingOnly);o.putBoolean("replant",replant);o.putBoolean("harvest_provision",harvestProvision);o.putInt("filter_cursor",filterCursor);o.putBoolean("exact",exact);o.putBoolean("match_damage",matchDamage);o.putBoolean("match_tags",matchTags);o.putBoolean("match_mod",matchMod);o.putBoolean("silk",silk);o.putBoolean("shared",shared);o.putInt("guard_mask",targets());o.putInt("guard_mode",guardMode);o.putBoolean("use_left",useLeft);o.putBoolean("use_air",useAir);o.putBoolean("use_empty",useEmpty);o.putBoolean("use_sneak",useSneak);o.putBoolean("use_provision",useProvision);for(int n=0;n<9;n++)o.putInt("amount_"+n,amounts[n]);o.putInt("revision",revision);}
    protected void loadAdditional(ValueInput i){super.loadAdditional(i);try{owner=UUID.fromString(i.getStringOr("owner",""));}catch(IllegalArgumentException e){owner=null;}channel=Math.clamp(i.getIntOr("channel",0),0,15);priority=Math.clamp(i.getIntOr("priority",0),-5,5);radius=Math.clamp(i.getIntOr("radius",3),1,8);configuredArea=i.read("seal_area",SealArea.CODEC).orElse(null);oriented=i.getBooleanOr("oriented_area",false)&&configuredArea!=null&&kind().hasArea();redstone=i.getBooleanOr("redstone",true);blacklist=i.getBooleanOr("blacklist",false);filter=i.read("filter",ItemStack.OPTIONAL_CODEC).orElse(ItemStack.EMPTY).copyWithCount(1);extraFilters.clear();i.read("filters",net.minecraft.world.item.component.ItemContainerContents.CODEC).ifPresent(c->c.copyInto(extraFilters));replants.clear();i.read("replants",com.mojang.serialization.Codec.unboundedMap(com.mojang.serialization.Codec.STRING,BlockState.CODEC)).ifPresent(map->map.forEach((p,state)->{try{if(replants.size()<256&&GolemCrops.seed(state)!=net.minecraft.world.item.Items.AIR)replants.put(BlockPos.of(Long.parseLong(p)),state);}catch(NumberFormatException ignored){}}));leaveOne=i.getBooleanOr("leave_one",false);single=i.getBooleanOr("single",false);cycle=i.getBooleanOr("cycle",false);existingOnly=i.getBooleanOr("existing_only",false);replant=i.getBooleanOr("replant",true);harvestProvision=i.getBooleanOr("harvest_provision",false);filterCursor=Math.clamp(i.getIntOr("filter_cursor",0),0,8);exact=i.getBooleanOr("exact",true);matchDamage=i.getBooleanOr("match_damage",exact);matchTags=i.getBooleanOr("match_tags",false);matchMod=i.getBooleanOr("match_mod",false);silk=i.getBooleanOr("silk",false)&&kind()==SealKind.BREAKER_ADVANCED;shared=i.getBooleanOr("shared",false);guardMask=Math.clamp(i.getIntOr("guard_mask",-1),-1,7);guardMode=kind()==SealKind.GUARD_ADVANCED?Math.clamp(i.getIntOr("guard_mode",0),0,2):0;for(int n=0;n<9;n++)amounts[n]=Math.clamp(i.getIntOr("amount_"+n,64),1,4096);useLeft=i.getBooleanOr("use_left",false);useAir=i.getBooleanOr("use_air",false);useEmpty=i.getBooleanOr("use_empty",false);useSneak=i.getBooleanOr("use_sneak",false);useProvision=i.getBooleanOr("use_provision",false);revision=i.getIntOr("revision",0);worker=null;lease=0;}
}
